INSERT INTO `posts` VALUES ('cmrlnfk160001h9un6xsxsl5s','Heo Quay Lá Mắc Mật — Đặc Sản Giao Thoa Hai Miền','{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Lá mắc mật — loài thảo mộc mọc hoang ở vùng núi phía Bắc — chính là linh hồn của món heo quay đặc sản Lạng Sơn. Khi kết hợp cùng kỹ thuật quay truyền thống, lớp da vàng ươm giòn tan hòa với hương thơm rừng núi tạo nên hương vị không thể lẫn đi đâu được.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Lá mắc mật là gì?","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Mắc mật (tên khoa học Clausena lansium) là loại cây thuộc họ Rutaceae, mọc tự nhiên ở các tỉnh miền núi Đông Bắc như Lạng Sơn, Cao Bằng, Bắc Kạn. Lá non có mùi thơm đặc trưng — pha giữa sả, quế và một chút cay nhẹ — không thể thay thế bằng loại thảo mộc nào khác.","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"\\"Thiếu lá mắc mật thì không thể gọi là heo quay Lạng Sơn.\\" — Nghệ nhân ẩm thực Hoàng Thị Lan, Lạng Sơn","type":"text"}]}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Nguyên liệu (cho 1 con heo 10–12 kg)","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"1 con heo sữa hoặc heo tơ 10–12 kg, đã làm sạch","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"300 g lá mắc mật tươi (hoặc 100 g lá khô)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"5 tbsp ngũ vị hương","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"3 tbsp nước tương đậm","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"2 tbsp mật ong","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"1 tbsp muối hột","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"1 tbsp đường vàng","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"1 tsp tiêu đen xay","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"3 tép tỏi băm nhuyễn","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Giấm trắng để phết da","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Cách làm","type":"text"}]},{"type":"heading","attrs":{"level":3,"textAlign":"left"},"content":[{"text":"Bước 1 — Sơ chế và nhồi lá","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Rửa sạch lá mắc mật, để ráo. Trộn lá với ngũ vị hương, nước tương, muối, tỏi băm và đường thành hỗn hợp nhồi. Nhồi toàn bộ hỗn hợp vào bụng heo, dùng que tre cố định bụng lại.","type":"text"}]},{"type":"heading","attrs":{"level":3,"textAlign":"left"},"content":[{"text":"Bước 2 — Ướp và phơi da","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Dùng que nhọn chích đều khắp mặt da. Phết giấm trắng lên toàn bộ da, đặt heo ở nơi thoáng gió ít nhất 4 tiếng (hoặc qua đêm trong tủ lạnh không che đậy). Da khô hoàn toàn là điều kiện bắt buộc để da giòn.","type":"text"}]},{"type":"heading","attrs":{"level":3,"textAlign":"left"},"content":[{"text":"Bước 3 — Quay","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Quay ở 220°C trong 20–25 phút đầu để da phồng và bắt màu. Hạ xuống 180°C, tiếp tục quay 60–80 phút tùy kích cỡ heo. Mỗi 20 phút phết một lớp mật ong pha loãng lên da để tạo màu vàng cánh gián đẹp mắt.","type":"text"}]},{"type":"heading","attrs":{"level":3,"textAlign":"left"},"content":[{"text":"Bước 4 — Để nguội và chặt","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Sau khi ra lò, để heo nghỉ 10 phút trước khi chặt — thịt sẽ giữ nước tốt hơn. Chặt miếng vừa ăn, bày ra đĩa với vài nhánh lá mắc mật tươi trang trí.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Ăn kèm gì ngon nhất?","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Xôi nếp nương — đặc trưng miền núi Bắc","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bánh mì nướng với tương hoisin","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dưa cải muối chua giải ngán","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rau sống: húng quế, rau mùi, ngò gai","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Mẹo từ bếp Heo Quay 47","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Nếu không tìm được lá mắc mật tươi, bạn có thể mua lá khô tại các chợ đầu mối ở Hà Nội hoặc đặt online. Lá khô cần ngâm nước 30 phút trước khi dùng. Hương thơm có thể nhạt hơn 20%, nhưng vẫn đủ đặc trưng.","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Tại Heo Quay 47, chúng tôi nhập lá mắc mật tươi từ Lạng Sơn mỗi tuần để đảm bảo hương vị chuẩn vị Bắc.","type":"text"}]}]}]}',1,0,'2026-07-15 05:37:59','2026-07-15 05:37:59','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Heo Quay Lá Mắc Mật Thơm Ngon","url":"/images/shop/heo-quay-can-1.jpg"}',0,NULL,'Heo quay lá mắc mật — đặc sản giao thoa ẩm thực Tây Nguyên và Nam Bộ. Hương thơm độc đáo, da giòn, thịt ngọt đặc trưng.',NULL,NULL,'wide',NULL,NULL,'heo-quay-la-mac-mat-dac-san-giao-thoa-hai-mien',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlnfly30007h9unzxiqf2kh','Đặt Heo Quay Cúng Giỗ — Những Điều Cần Biết','{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Heo quay là lễ vật không thể thiếu trong các dịp giỗ chạp, cúng rằm tháng Bảy, cúng Ông Táo hay cúng đất. Đặt heo quay cúng có một số điểm khác với đặt heo quay thông thường mà không phải ai cũng biết.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Kích thước và trọng lượng phù hợp","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Trọng lượng heo quay cúng thường được tính dựa theo số người dùng bữa sau lễ cúng:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Gia đình nhỏ 4–6 người: heo sữa 3–5 kg (còn gọi là heo quay cúng nhỏ)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Gia đình 10–15 người: heo tơ 6–8 kg","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tiệc giỗ 20–30 người: heo 10–12 kg","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Giỗ lớn, cúng đình: heo 15–20 kg trở lên","type":"text"}]}]}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Tại Heo Quay 47, chúng tôi cung cấp heo sữa từ 3 kg (nguyên con) phù hợp cho lễ cúng tại nhà.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Đặt trước bao lâu?","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Tối thiểu 2 ngày trước","type":"text","marks":[{"type":"bold"}]},{"text":" ngày cúng. Nếu cúng vào cuối tuần hoặc ngày rằm, mùng một, nên đặt trước ","type":"text"},{"text":"3–5 ngày","type":"text","marks":[{"type":"bold"}]},{"text":" để đảm bảo có hàng. Dịp Thanh Minh, Vu Lan (tháng 7 âm lịch) và cuối năm âm lịch thường rất đông — nên đặt trước ít nhất 1 tuần.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Giờ giao hàng","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Lễ cúng thường diễn ra vào buổi sáng (9–11 giờ). Do đó giờ giao lý tưởng là 7–8 giờ sáng để heo còn nóng, da còn giòn khi lên mâm. Chúng tôi nhận đơn giao từ 7:00 sáng cho đơn đặt trước.","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Lưu ý: Heo Quay 47 giao hàng Thứ 2 đến Thứ 6. Nếu ngày cúng rơi vào Thứ 7 hoặc Chủ Nhật, vui lòng liên hệ trực tiếp để thỏa thuận.","type":"text"}]}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Heo quay nguyên con hay theo miếng?","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Cúng giỗ truyền thống yêu cầu heo quay nguyên con — đầu heo, thân và bốn chân đầy đủ, không chặt. Sau khi cúng xong mới chặt phục vụ bữa ăn. Chúng tôi giao nguyên con, kèm dao chặt và hướng dẫn chặt nếu cần.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Chuẩn bị mâm cúng","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Heo quay thường được đặt trên khay inox hoặc mâm gỗ lớn, đầu hướng ra ngoài (hướng về bàn thờ hoặc trước sân). Trang trí đơn giản với vài bông hoa cúc vàng và lá lộc.","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Không cần cắt trang trí phức tạp — giữ nguyên con để thể hiện sự trang trọng","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Đặt kèm muối trắng và gừng tươi bên cạnh","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Có thể kèm theo bánh chưng hoặc xôi gấc tùy phong tục vùng miền","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Liên hệ đặt hàng","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Gọi hotline hoặc điền form đặt lịch trên website. Vui lòng ghi rõ: ngày giao, giờ giao, trọng lượng mong muốn và địa chỉ. Chúng tôi sẽ xác nhận đơn trong vòng 2 giờ làm việc.","type":"text"}]}]}',1,0,'2026-07-15 05:38:02','2026-07-15 05:38:02','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Heo Quay Cúng Giỗ Trang Trọng","url":"/images/shop/heo-sua-doi-1.jpg"}',0,NULL,'Hướng dẫn đặt heo quay cúng giỗ đúng nghi lễ — kích cỡ phù hợp, cách bày mâm và lưu ý quan trọng khi chọn heo quay cho lễ cúng.',NULL,NULL,'minimal',NULL,NULL,'dat-heo-quay-cung-gio-nhung-dieu-can-biet',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlnfn7a000bh9uns5iqlqpo','Heo Quay 47 — Câu Chuyện Từ Bếp Lửa Gia Đình','{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"\\"47\\" không phải con số ngẫu nhiên. Đó là số nhà nơi bà ngoại tôi đã nuôi heo và quay heo suốt 30 năm ở một con hẻm nhỏ Bình Tân. Heo Quay 47 ra đời từ ký ức đó — và từ một câu hỏi đơn giản: liệu có thể đưa hương vị bếp nhà ra ngoài mà không mất đi điều gì?","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Bắt đầu từ một ký ức","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Mỗi dịp giỗ, bà tôi dậy từ 4 giờ sáng. Không phải vì bà phải làm nhiều việc — mà vì bà muốn có đủ thời gian. Thời gian để heo thấm gia vị. Thời gian để da khô tự nhiên trong gió sớm. Thời gian để lửa than đỏ đều trước khi đặt heo lên.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Không có nhiệt kế, không có hẹn giờ. Chỉ có kinh nghiệm và sự kiên nhẫn. Miếng heo bà quay luôn có lớp da phồng đều, giòn tan khi cắn — không một vết cháy, không một chỗ mềm. Hàng xóm xung quanh thường ghé qua không phải để hỏi thăm, mà để hỏi mua.","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"\\"Con heo ngon hay không là do người quay có kiên nhẫn không, chứ không phải do gia vị nhiều hay ít.\\" — Bà ngoại Tám","type":"text"}]}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Khi bếp nhà trở thành thương hiệu","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Năm 2019, sau nhiều năm học và làm công việc không liên quan đến bếp núc, tôi quyết định quay lại với điều duy nhất mình thực sự biết làm tốt. Mang công thức của bà, học thêm kỹ thuật kiểm soát nhiệt độ hiện đại, và bắt đầu nhận đơn từ bạn bè.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Tuần đầu: 5 đơn. Tháng thứ ba: 50 đơn. Năm thứ hai: thuê thêm người và mở rộng bếp.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Điều tôi không muốn thay đổi: vẫn dùng đúng lá mắc mật từ Lạng Sơn, vẫn phơi da qua đêm, vẫn không dùng phụ gia để làm da giòn nhân tạo. Điều tôi học thêm: kiểm soát nhiệt độ bằng nhiệt kế, chuẩn hóa công thức ướp để mỗi con heo ra lò đều giống nhau.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Điều chúng tôi cam kết","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Heo tươi mổ trong ngày, không dùng heo đông lạnh","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Không dùng phụ gia tạo giòn, tạo màu nhân tạo","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lá mắc mật nhập trực tiếp từ Lạng Sơn mỗi tuần","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Giao đúng giờ — cam kết bồi thường nếu trễ quá 30 phút","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Không giao Thứ 7 và Chủ Nhật để đảm bảo chất lượng kiểm soát","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Heo Quay 47 hôm nay","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Chúng tôi hiện phục vụ trên 200 đơn mỗi tháng, từ tiệc gia đình đến sự kiện doanh nghiệp, cúng giỗ đến khai trương. Mỗi con heo vẫn do chính tôi hoặc người học trực tiếp từ tôi thực hiện — chưa bao giờ khoán cho người chưa đủ 6 tháng thực hành.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Con số 47 vẫn ở đó — nhắc tôi rằng điều quan trọng nhất không phải là bao nhiêu đơn, mà là mỗi miếng heo ra lò có xứng đáng với tiêu chuẩn của bà không.","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Đặt hàng sớm — đặc biệt dịp lễ và cuối năm. Chúng tôi không nhận thêm đơn khi đã đủ công suất trong ngày.","type":"text"}]}]}]}',1,0,'2026-07-15 05:38:03','2026-07-15 05:38:03','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Heo Quay 47 Bình Tân","url":"/images/shop/heo-quay-khay-1.jpg"}',0,NULL,'Câu chuyện về Heo Quay 47 — thương hiệu heo quay gia truyền tại Bình Tân. Hơn 20 năm giữ lửa bếp quay truyền thống.',NULL,NULL,'wide',NULL,NULL,'heo-quay-47-cau-chuyen-tu-bep-lua-gia-dinh',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlnfkoi0003h9unc5ah9ymj','Gà Quay Mật Ong — Da Giòn, Thịt Ngọt, Không Bở','{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Gà quay mật ong là món quen thuộc nhưng để làm đúng — da giòn mà không cháy, thịt mềm mà không bở, màu vàng cánh gián tự nhiên — lại cần hiểu đúng từng bước. Bài này chia sẻ công thức chúng tôi đang dùng tại Heo Quay 47.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Chọn gà","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Gà ta hoặc gà Đông Tảo 1.5–2 kg cho kết quả tốt nhất. Gà công nghiệp da dày, mỡ nhiều — khó giòn và hay bị cháy ngoài sống trong. Gà phải tươi, không đông lạnh; da còn nguyên vẹn, không rách.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Nguyên liệu","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"1 con gà ta 1.5–2 kg","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"3 tbsp mật ong (loại đậm màu như mật ong rừng)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"2 tbsp nước tương","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"1 tbsp dầu hào","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"1 tsp ngũ vị hương","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"1 tsp bột tỏi","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"1 tsp bột gừng","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"½ tsp muối","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"1 tbsp giấm táo (để phết da)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dầu ăn để phết trước khi quay","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Kỹ thuật làm da giòn","type":"text"}]},{"type":"heading","attrs":{"level":3,"textAlign":"left"},"content":[{"text":"Quan trọng nhất: làm khô da","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Dùng khăn giấy thấm khô toàn bộ mặt da. Phết giấm táo lên da, để tủ lạnh 8–12 tiếng không che đậy. Hơi lạnh trong tủ sẽ hút ẩm từ da ra ngoài — đây là bước nhiều người bỏ qua dẫn đến da không giòn.","type":"text"}]},{"type":"heading","attrs":{"level":3,"textAlign":"left"},"content":[{"text":"Chích da đều tay","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Dùng nĩa hoặc kim chích đều khắp mặt da, đặc biệt phần ngực và đùi. Chích giúp mỡ dưới da thoát ra trong quá trình quay thay vì đọng lại làm da mềm.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Công thức ướp","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Trộn mật ong, nước tương, dầu hào, ngũ vị hương, bột tỏi, bột gừng và muối. Phết đều vào bên trong bụng gà trước, sau đó mới phết ngoài da. Để ướp tối thiểu 4 tiếng — lý tưởng là qua đêm.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Nhiệt độ và thời gian","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Làm nóng lò 220°C (đặt khay dưới đáy để hứng mỡ)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Đặt gà lên vỉ, phết một lớp dầu mỏng lên da","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Quay 220°C — 20 phút đầu để da phồng và bắt màu","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Hạ xuống 180°C — tiếp tục 25–30 phút","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kiểm tra: xiên vào phần đùi dày nhất, nước chảy ra trong là chín","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Phết thêm mật ong pha loãng 1:1 với nước, bật broil (lửa trên) 3–5 phút để màu đẹp","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Để gà không bị bở","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Không quay quá lâu — thịt gà chín ở 74°C bên trong","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Để gà nghỉ 10 phút sau khi ra lò trước khi chặt","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Không mở lò thường xuyên trong quá trình quay (mất nhiệt, thịt co lại)","type":"text"}]}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Mẹo nhỏ: thêm vài lát gừng và sả vào bụng gà trước khi quay — mùi thơm lan vào thịt rất tự nhiên.","type":"text"}]}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Nước chấm đi kèm","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Gà quay mật ong ngon nhất khi chấm muối tiêu chanh truyền thống hoặc tương xí muội. Tránh dùng tương hoisin vì vị ngọt đã có trong mật ong, ăn sẽ bị ngấy.","type":"text"}]}]}',0,0,'2026-07-15 05:38:00','2026-07-15 05:38:00','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Gà Quay Mật Ong Da Giòn","url":"https://images.unsplash.com/photo-1527477396000-e27163b481c2?w=1200&q=85"}',0,NULL,'Gà quay mật ong da giòn vàng ươm, thịt ngọt không bở. Bí quyết phết mật ong đúng cách để da bóng caramel đẹp mắt.',NULL,NULL,'standard',NULL,NULL,'ga-quay-mat-ong-da-gion-thit-ngot-khong-bo',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlnflbf0005h9unr6z25dqu','Tại Sao Da Heo Quay Không Giòn? 7 Lỗi Thường Gặp','{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Da giòn là tiêu chí số một của một miếng heo quay ngon. Nhưng không ít người thử đi thử lại mà da vẫn mềm, dai hoặc cháy loang lổ. Bài này tổng hợp 7 lỗi phổ biến nhất và cách khắc phục từng lỗi.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Lỗi 1 — Da còn ẩm trước khi quay","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Đây là nguyên nhân số một. Độ ẩm trong da sẽ tạo hơi nước khi gặp nhiệt, làm da phồng lên rồi xẹp xuống thay vì giòn đều.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Cách khắc phục: ","type":"text","marks":[{"type":"bold"}]},{"text":"Sau khi ướp, để heo trong tủ lạnh không che đậy ít nhất 8 tiếng. Lấy ra trước khi quay 30 phút để về nhiệt độ phòng, dùng khăn giấy thấm lại một lần nữa.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Lỗi 2 — Không chích da","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Da heo có lớp mỡ dày phía dưới. Nếu không chích, mỡ không thoát ra được, tích tụ dưới da và làm da mềm ủng.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Cách khắc phục: ","type":"text","marks":[{"type":"bold"}]},{"text":"Dùng kim hoặc nĩa chích đều khắp mặt da, sâu khoảng 3–4 mm. Tập trung vào phần lưng và vai nơi mỡ dày nhất. Không cần chích phần bụng.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Lỗi 3 — Ướp gia vị lên da","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Nước tương, mật ong, dầu hào — dù ngon nhưng đều chứa đường và nước. Phết lên da trước khi quay làm da không bao giờ khô được.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Cách khắc phục: ","type":"text","marks":[{"type":"bold"}]},{"text":"Ướp gia vị bên trong bụng và phần thịt, không phết lên da. Chỉ phết mật ong pha loãng lên da trong 5–10 phút cuối để tạo màu.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Lỗi 4 — Nhiệt độ lò không đủ cao lúc đầu","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Nếu bắt đầu quay ở nhiệt độ thấp, da sẽ nấu chín dần thay vì phồng nhanh. Kết quả là da chín nhưng không giòn.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Cách khắc phục: ","type":"text","marks":[{"type":"bold"}]},{"text":"Luôn bắt đầu ở 220–230°C trong 20 phút đầu để da phồng và bắt màu. Sau đó mới hạ nhiệt để thịt bên trong chín đều.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Lỗi 5 — Mở lò quá nhiều lần","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Mỗi lần mở lò, nhiệt độ giảm đột ngột 20–30°C. Dao động nhiệt liên tục làm da co lại rồi giãn ra, mất đi độ giòn.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Cách khắc phục: ","type":"text","marks":[{"type":"bold"}]},{"text":"Chỉ mở lò tối đa 2 lần: một lần để lật (nếu cần) và một lần để phết mật ong cuối. Dùng đèn bên trong lò để quan sát thay vì mở cửa.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Lỗi 6 — Dùng heo đông lạnh","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Thịt đông lạnh sau khi rã đông tiết ra nhiều nước, đặc biệt ở lớp da. Dù phơi và lau khô bao nhiêu, da vẫn chứa ẩm nhiều hơn heo tươi.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Cách khắc phục: ","type":"text","marks":[{"type":"bold"}]},{"text":"Dùng heo tươi mổ trong ngày. Nếu buộc dùng đông lạnh, rã đông trong tủ lạnh 24 tiếng (không rã ở nhiệt độ phòng), sau đó phơi khô ít nhất 12 tiếng.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Lỗi 7 — Không để heo nghỉ sau khi ra lò","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Chặt ngay khi vừa ra lò, hơi nước bên trong thịt thoát ra, ngấm lên da và làm da mềm chỉ sau vài phút.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Cách khắc phục: ","type":"text","marks":[{"type":"bold"}]},{"text":"Để heo nghỉ trên vỉ (không để trên đĩa phẳng) 8–10 phút sau khi ra lò trước khi chặt. Đặt trên vỉ giúp không khí lưu thông, da tiếp tục giòn.","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Tóm lại: khô da + nhiệt cao ban đầu + không mở lò thường xuyên = da giòn. Đơn giản nhưng đòi hỏi kỷ luật ở từng bước.","type":"text"}]}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Checklist nhanh trước khi quay","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"✅ Da đã phơi ít nhất 8 tiếng trong tủ lạnh","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"✅ Da đã được chích đều","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"✅ Không có gia vị trên mặt da","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"✅ Lò đã làm nóng sẵn 220°C","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"✅ Không mở lò trong 20 phút đầu","type":"text"}]}]}]}]}',0,0,'2026-07-15 05:38:01','2026-07-15 05:38:01','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Heo Quay Trong Lò Đúng Kỹ Thuật","url":"/images/shop/heo-quay-lo-3.jpg"}',0,NULL,'Tại sao da heo quay không giòn? Phân tích 7 lỗi thường gặp nhất và cách khắc phục để luôn có lớp da heo quay giòn rụm đúng chuẩn.',NULL,NULL,'standard',NULL,NULL,'tai-sao-da-heo-quay-khong-gion-7-loi-thuong-gap',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlnfmkp0009h9un79rybq3g','Bảo Quản Heo Quay — Giữ Da Giòn Cả Ngày Không Lo','{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Heo quay ngon nhất trong 2 giờ đầu sau khi ra lò. Nhưng nếu bạn đặt giao buổi sáng để dùng bữa trưa, hay có tiệc kéo dài nhiều giờ — biết cách bảo quản đúng sẽ giúp da giòn lâu hơn đáng kể.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Tại sao da heo quay bị mềm?","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Da heo quay mềm vì một nguyên nhân duy nhất: hơi nước. Hơi nước từ thịt bên trong bốc lên, kết hợp với độ ẩm không khí và đọng lại trên bề mặt da, làm da mất độ giòn. Quá trình này diễn ra ngay khi heo ra khỏi lò.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Cách giữ giòn trong 2–4 giờ","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Đây là tình huống phổ biến nhất: heo giao lúc 10 giờ, ăn lúc 12 giờ trưa.","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Để heo trên vỉ, không để trực tiếp trên khay hay đĩa phẳng — hơi nước phía dưới sẽ làm ẩm phần bụng","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Đặt nơi thoáng, nhiệt độ phòng, tránh điều hòa thổi thẳng vào","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Không bọc hoặc đậy nắp — bọc kín sẽ giữ hơi nước lại","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nếu có lò nướng, bật 150°C và để heo trong lò (cửa hé nhẹ) để giữ ấm và duy trì độ giòn","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Cách giữ giòn sau 4–8 giờ","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Khi cần giữ lâu hơn (cỗ giỗ ăn nhiều đợt, tiệc dài), heo quay đã nguội cần được hâm lại đúng cách:","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Để heo nguội hoàn toàn về nhiệt độ phòng","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bật lò 200°C, để heo trực tiếp lên vỉ (không dùng khay)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Hâm 12–15 phút — da sẽ giòn lại như mới","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Không dùng lò vi sóng — da sẽ mềm nhũn hoàn toàn và không thể phục hồi","type":"text"}]}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"Nồi chiên không dầu (air fryer) rất tốt để hâm miếng nhỏ: 180°C / 5–7 phút, da giòn đều và nhanh hơn lò nướng thông thường.","type":"text"}]}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Bảo quản qua đêm","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Nếu có heo quay thừa sau tiệc:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Để nguội hoàn toàn, bọc thịt (không bọc da) bằng giấy bạc","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Cất ngăn mát tủ lạnh, dùng trong 2 ngày","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Khi ăn: hâm bằng lò nướng hoặc air fryer, không dùng lò vi sóng","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tuyệt đối không đông lạnh — cấu trúc da bị phá vỡ, không thể giòn lại","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Bảo quản để vận chuyển xa","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":"left"},"content":[{"text":"Nếu cần mang heo quay đi xa (tiệc ngoài trời, nhà khách xa):","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bọc toàn bộ heo bằng giấy bạc để giữ nhiệt, không dùng màng bọc thực phẩm","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Đặt trong thùng xốp (không cần đá lạnh nếu vận chuyển dưới 2 tiếng)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Khi đến nơi, mở giấy bạc ngay để da không bị ngạt hơi","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nếu có lò tại chỗ, hâm lại 10 phút trước khi phục vụ","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2,"textAlign":"left"},"content":[{"text":"Tóm tắt nhanh","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Giòn ngay sau quay: vỉ thoáng, không bọc, không che","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Giữ 2–4 giờ: để trên vỉ, lò 150°C cửa hé","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Hâm lại: lò 200°C / 12–15 phút hoặc air fryer 180°C / 5–7 phút","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tủ lạnh: bọc thịt (không bọc da), dùng trong 2 ngày","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Cấm: lò vi sóng, đông lạnh, bọc kín khi còn nóng","type":"text"}]}]}]}]}',0,0,'2026-07-15 05:38:03','2026-07-15 05:38:03','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Heo Quay Đóng Gói Bảo Quản","url":"/images/shop/heo-quay-khay-1.jpg"}',0,NULL,'Bí quyết giữ da heo quay giòn cả ngày — từ cách bọc, cách để đến cách hâm lại đúng kỹ thuật không làm mềm da.',NULL,NULL,'standard',NULL,NULL,'bao-quan-heo-quay-giu-da-gion-ca-ngay-khong-lo',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrltx3jv0007h9yr17rxzau2','Đặt Vịt Nướng Cho Tiệc — Heo Quay Bình Tân Phục Vụ Tận Nơi','{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Đặt Vịt Nướng Cho Tiệc — Heo Quay Bình Tân Phục Vụ Tận Nơi","type":"text"}]}]}',0,0,'2026-07-15 08:39:35','2026-07-15 08:39:35','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Đặt Vịt Nướng Cho Tiệc Bình Tân","url":"/images/shop/heo-sua-hop-3.jpg"}',0,NULL,'Đặt vịt nướng cho tiệc tại Bình Tân. Nhận đặt vịt nướng số lượng lớn cho cưới hỏi, giỗ chạp, sinh nhật. Giao hàng tận nơi.',NULL,NULL,'standard',NULL,NULL,'dat-vit-nuong-cho-tiec-heo-quay-binh-tan-phuc-vu-tan-noi',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlno9tw000ih9ja1jn8y715','Vịt Quay Chao — Đặc Sản Miền Nam Thơm Béo Khó Quên','{"time":1784094280189,"blocks":[{"data":{"text":"Vịt quay chao là một biến tấu độc đáo của miền Nam Việt Nam, dùng chao (đậu hũ lên men) thay cho ngũ vị hương truyền thống. Vị béo thơm đặc trưng của chao thấm vào thịt vịt tạo nên hương vị khó tìm thấy ở bất kỳ đâu."},"type":"paragraph"},{"data":{"text":"Chao — nguyên liệu đặc biệt tạo nên sự khác biệt","level":2},"type":"header"},{"data":{"text":"Chao là đậu hũ được ủ với muối và rượu trong nhiều tuần, tạo ra vị béo mặn đặc trưng. Khi ướp vịt, chao tan vào thịt tạo lớp màu vàng nâu đẹp và mùi thơm béo ngậy không lẫn vào đâu được. Nên dùng chao đỏ (chao Nam Bộ) để có màu đẹp hơn chao trắng."},"type":"paragraph"},{"data":{"text":"Công thức ướp vịt quay chao","level":2},"type":"header"},{"data":{"items":["3–4 miếng chao đỏ nghiền nát","2 thìa nước tương","1 thìa mật ong","1 thìa ngũ vị hương","Tỏi gừng sả băm nhuyễn","1 thìa đường, muối, tiêu"],"style":"unordered"},"type":"list"},{"data":{"text":"Ăn kèm gì ngon nhất?","level":2},"type":"header"},{"data":{"text":"Vịt quay chao ngon nhất khi ăn với bánh mì hoặc bún tươi, kèm dưa leo, rau thơm và nước tương gừng. Một số quán ở miền Tây còn phục vụ kèm dưa cải muối chua — vị chua của dưa cân bằng hoàn hảo với độ béo của chao."},"type":"paragraph"}]}',1,0,'2026-07-15 05:44:46','2026-07-15 05:44:46','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Món Quay Heo Quay Bình Tân","url":"/images/shop/heo-sua-can-2.jpg"}',0,NULL,'Vịt quay chao đặc sản miền Nam — vị béo thơm của chao đỏ thấm vào thịt vịt. Công thức ướp và cách ăn kèm đúng điệu miền Tây.',NULL,NULL,'standard',NULL,NULL,'vit-quay-chao-dac-san-mien-nam-thom-beo-kho-quen',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlno853000ah9jacpitf53r','Heo Quay Miền Tây — Hương Vị Sả Gừng Khói Than Độc Đáo','{"time":1784094280189,"blocks":[{"data":{"text":"Heo quay miền Tây Nam Bộ có những nét đặc trưng riêng, khác biệt so với heo quay Sài Gòn hay phong cách Quảng Đông. Sự khác biệt đến từ nguyên liệu địa phương, kỹ thuật quay trên than củi và cách thưởng thức dân dã."},"type":"paragraph"},{"data":{"text":"Gia vị đặc trưng miền Tây","level":2},"type":"header"},{"data":{"text":"Heo quay miền Tây thường dùng sả và gừng nhiều hơn trong hỗn hợp ướp, tạo mùi thơm đặc trưng. Một số nơi còn thêm lá chanh và nghệ tươi để tạo màu vàng tự nhiên và hương thơm khác biệt so với ngũ vị hương truyền thống."},"type":"paragraph"},{"data":{"text":"Kỹ thuật quay trên than củi lộ thiên","level":2},"type":"header"},{"data":{"text":"Thay vì lò quay công nghiệp, heo quay miền Tây thường được quay trên bếp than củi ngoài trời. Hơi nhiệt lan tỏa tự nhiên, kết hợp với khói củi tạo nên mùi thơm mà lò hiện đại không thể tái tạo được."},"type":"paragraph"},{"data":{"text":"Cách ăn kèm đặc trưng","level":2},"type":"header"},{"data":{"items":["Ăn với bánh mì — phổ biến nhất, cắt miếng to kẹp bánh mì nóng","Cuốn bánh tráng — thêm dưa leo, rau thơm, bún tươi bên trong","Chấm nước tương gừng — đơn giản nhưng đậm vị","Ăn kèm dưa cải muối chua — cắt béo, giải ngán"],"style":"unordered"},"type":"list"}]}',1,0,'2026-07-15 05:44:44','2026-07-15 05:44:44','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Heo Quay Vàng Giòn Miền Tây","url":"/images/shop/heo-quay-can-2.jpg"}',0,NULL,'Heo quay miền Tây Nam Bộ — hương vị sả gừng khói than độc đáo. Cách ăn kèm bánh mì, bánh tráng đặc trưng miền Tây.',NULL,NULL,'standard',NULL,NULL,'heo-quay-mien-tay-huong-vi-sa-gung-khoi-than-doc-dao',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlnxmi50006h9xj30yg2ngb','Phân Biệt Heo Sữa Quay Ngon và Heo Sữa Kém Chất Lượng','{"time":1784094719384,"blocks":[{"data":{"text":"Trên thị trường có rất nhiều nơi bán heo sữa quay, nhưng chất lượng chênh lệch rất lớn. Biết cách phân biệt sẽ giúp bạn không bị mua phải hàng kém, đặc biệt trong các dịp tiệc quan trọng."},"type":"paragraph"},{"data":{"text":"Nhìn — màu sắc nói lên tất cả","level":2},"type":"header"},{"data":{"items":["Tốt: da màu đỏ vàng đẹp, đều, không có đốm cháy đen","Tốt: bề mặt bóng nhẹ tự nhiên, không bóng loáng quá mức (dấu hiệu phẩm màu)","Kém: màu đỏ gắt bất thường — dùng phẩm màu hoặc xi-rô đậm","Kém: có vùng trắng nhợt chưa chín hoặc đen cháy không đều"],"style":"unordered"},"type":"list"},{"data":{"text":"Gõ — nghe tiếng da","level":2},"type":"header"},{"data":{"text":"Dùng đũa gõ nhẹ lên da: nghe tiếng gõ giòn rỗng là da đạt chuẩn. Tiếng gõ đặc bịch là da còn mềm hoặc đã mềm do để lâu. Đây là test nhanh nhất và chính xác nhất bạn có thể làm tại chỗ."},"type":"paragraph"},{"data":{"text":"Cắt — xem thịt bên trong","level":2},"type":"header"},{"data":{"items":["Tốt: thịt màu trắng hồng đều, không có nước đỏ chảy ra","Tốt: lớp mỡ mỏng dưới da, không dày quá 5mm","Kém: thịt còn hồng đỏ bên xương — chưa chín kỹ","Kém: mỡ dày và nhão — heo quá lớn bị bán nhầm là heo sữa"],"style":"unordered"},"type":"list"},{"data":{"text":"Heo sữa thật vs heo nhỏ giả sữa","level":2},"type":"header"},{"data":{"text":"Heo sữa thật phải còn đang bú mẹ, dưới 21 ngày tuổi, nặng tối đa 6 kg. Một số nơi dùng heo con đã cai sữa (4–5 tuần, 7–10 kg) để bán với giá heo sữa. Cách phân biệt: heo sữa thật thịt trắng muốt, không mùi; heo cai sữa thịt hồng đậm hơn và có mùi heo nhẹ."},"type":"paragraph"}]}',0,0,'2026-07-15 05:52:02','2026-07-15 05:52:02','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Heo Sữa Quay Chất Lượng Cao","url":"/images/shop/heo-sua-doi-1.jpg"}',0,NULL,'Cách phân biệt heo sữa quay ngon và kém chất lượng: nhìn màu da, gõ nghe tiếng, cắt xem thịt. Tránh mua heo cai sữa giả heo sữa.',NULL,NULL,'standard',NULL,NULL,'phan-biet-heo-sua-quay-ngon-va-heo-sua-kem-chat-luong',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlnoa8v000kh9ja9pec4tlx','Vịt Quay Quảng Đông — Cách Làm Chuẩn Vị Nhà Hàng Tại Nhà','{"time":1784094280189,"blocks":[{"data":{"text":"Vịt quay Quảng Đông khác với vịt quay Bắc Kinh ở chỗ thịt được ướp gia vị nhiều hơn, da không cần mỏng như giấy nhưng vẫn đạt độ giòn và màu đỏ nâu bóng đặc trưng. Đây là phong cách phổ biến nhất ở các nhà hàng Hoa tại TP.HCM."},"type":"paragraph"},{"data":{"text":"Nhồi gia vị bên trong — bí quyết của nhà hàng","level":2},"type":"header"},{"data":{"text":"Thay vì chỉ xoa ướp, vịt quay Quảng Đông có bước nhồi gia vị lỏng vào bên trong bụng vịt rồi dùng xiên khâu kín lại. Trong quá trình quay, gia vị lỏng sôi bên trong tạo áp lực, giúp thịt chín từ trong ra ngoài và thấm gia vị đều hơn."},"type":"paragraph"},{"data":{"text":"Hỗn hợp gia vị nhồi (cho 1 con vịt 2 kg)","level":2},"type":"header"},{"data":{"items":["3 thìa nước tương đậm","2 thìa dầu hào","1 thìa ngũ vị hương","1 thìa đường phèn","200ml nước","Hành tím, tỏi, gừng, sả đập dập"],"style":"unordered"},"type":"list"},{"data":{"text":"Lớp áo ngoài tạo màu và độ giòn","level":2},"type":"header"},{"data":{"text":"Hỗn hợp phết ngoài da: mạch nha + giấm gạo + nước tương nhạt theo tỷ lệ 2:2:1. Sau khi trụng vịt qua nước sôi, phết ngay khi da còn nóng để hỗn hợp bám đều. Phơi quạt 4–6 tiếng cho da khô hoàn toàn trước khi quay ở 200°C khoảng 50–60 phút."},"type":"paragraph"}]}',0,0,'2026-07-15 05:44:47','2026-07-15 05:44:47','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Vịt Quay Quảng Đông Da Giòn","url":"https://images.unsplash.com/photo-1518492104633-130d0cc84637?w=1200&q=85"}',0,NULL,'Vịt quay Quảng Đông chuẩn vị nhà hàng người Hoa. Bí quyết nhồi gia vị bên trong và lớp áo ngoài da giòn vàng đỏ đẹp.',NULL,NULL,'standard',NULL,NULL,'vit-quay-quang-dong-cach-lam-chuan-vi-nha-hang-tai-nha',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlno8zl000eh9jazkmv5np7','Gà Quay Muối — Công Thức Truyền Thống Người Hoa Tại Sài Gòn','{"time":1784094280189,"blocks":[{"data":{"text":"Gà quay muối là món gà không quá cầu kỳ nhưng đòi hỏi kỹ thuật tinh tế. Da vàng ươm, thịt mềm ngọt, chấm muối tiêu chanh — đơn giản mà không kém phần sang trọng trong ẩm thực người Hoa ở Sài Gòn."},"type":"paragraph"},{"data":{"text":"Bí quyết da vàng không cần lò nướng","level":2},"type":"header"},{"data":{"text":"Khác với gà quay thông thường, gà quay muối dùng kỹ thuật luộc rồi ngâm lạnh và chiên giòn. Gà được luộc trong nước dùng xương có gừng và hành cho chín tới, sau đó ngâm ngay vào nước đá để da căng và giòn. Bước cuối chiên ngập dầu ở 190°C cho đến khi da vàng giòn đều."},"type":"paragraph"},{"data":{"text":"Muối tiêu chanh — nước chấm không thể thiếu","level":2},"type":"header"},{"data":{"items":["2 thìa muối hột rang khô cho dậy mùi","1 thìa tiêu xay thô","1/2 thìa đường","Trộn đều, khi ăn vắt chanh tươi vào","Có thể thêm ớt tươi thái lát"],"style":"unordered"},"type":"list"}]}',1,0,'2026-07-15 05:44:45','2026-07-15 05:44:45','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Món Quay Heo Quay Bình Tân","url":"/images/shop/heo-sua-khay-1.jpg"}',0,NULL,'Gà quay muối kiểu người Hoa Sài Gòn — da vàng giòn không cần lò nướng. Công thức muối tiêu chanh truyền thống ăn kèm.',NULL,NULL,'standard',NULL,NULL,'ga-quay-muoi-cong-thuc-truyen-thong-nguoi-hoa-tai-sai-gon',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlno8kh000ch9ja79kfxgkp','Gà Quay Ngũ Vị — Thơm Lừng Từ Trong Ra Ngoài','{"time":1784094280189,"blocks":[{"data":{"text":"Gà quay ngũ vị là công thức kinh điển của ẩm thực Á Đông, kết hợp hoàn hảo giữa hương thơm của ngũ vị hương và vị ngọt tự nhiên của gà ta. Lớp da vàng giòn, thịt mềm thấm đều gia vị — món ăn không bao giờ lỗi thời."},"type":"paragraph"},{"data":{"text":"Nguyên liệu cho 1 con gà 1.5–2 kg","level":2},"type":"header"},{"data":{"items":["1 con gà ta khoảng 1.5–2 kg","1.5 thìa ngũ vị hương","2 thìa nước tương đậm","1 thìa dầu hào","1 thìa mật ong","1 thìa rượu trắng","4 tép tỏi + 1 củ gừng nhỏ băm nhuyễn","1 thìa đường, muối, tiêu"],"style":"unordered"},"type":"list"},{"data":{"text":"Kỹ thuật nướng để da giòn đều","level":2},"type":"header"},{"data":{"items":["Lấy gà ra khỏi tủ lạnh 30 phút trước khi nướng","Nướng 210°C trong 20 phút đầu — da phồng và bắt đầu giòn","Hạ xuống 175°C nướng thêm 30–35 phút","Phết thêm mật ong pha nước tương trong 5 phút cuối","Để nghỉ 10 phút trước khi chặt"],"style":"unordered"},"type":"list"}]}',0,0,'2026-07-15 05:44:44','2026-07-15 05:44:44','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Gà Quay Ngũ Vị Hương","url":"https://images.unsplash.com/photo-1527477396000-e27163b481c2?w=1200&q=85"}',0,NULL,'Gà quay ngũ vị thơm lừng từ trong ra ngoài. Công thức ướp và kỹ thuật nướng để da giòn đều, thịt mềm ngọt chuẩn vị Á Đông.',NULL,NULL,'standard',NULL,NULL,'ga-quay-ngu-vi-thom-lung-tu-trong-ra-ngoai',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlno6va0004h9jax2drs91k','Heo Quay Sữa — Da Mỏng Giòn Tan, Thịt Mềm Ngọt Đặc Trưng','{"time":1784094280189,"blocks":[{"data":{"text":"Heo quay sữa là món ăn cao cấp dùng heo con còn đang bú mẹ, khoảng 3–5 kg. Da cực mỏng, thịt mềm ngọt tự nhiên, không có mỡ dày như heo trưởng thành — đây là lý do heo quay sữa luôn được ưa chuộng trong tiệc cưới và sự kiện quan trọng."},"type":"paragraph"},{"data":{"text":"Chọn heo sữa đúng chuẩn","level":2},"type":"header"},{"data":{"items":["Chọn heo 3–5 kg — quá nhỏ ít thịt, quá lớn da dày khó giòn","Da trắng hồng, mịn đều không có vết thâm","Heo còn bú mẹ hoàn toàn — thịt mới ngọt tự nhiên","Mua từ trại uy tín, có nguồn gốc rõ ràng"],"style":"unordered"},"type":"list"},{"data":{"text":"Ướp gia vị đơn giản — để vị thịt tự nhiên lên ngôi","level":2},"type":"header"},{"data":{"text":"Khác với heo lớn cần ướp đậm, heo sữa chỉ cần ướp nhẹ để giữ vị ngọt tự nhiên của thịt. Hỗn hợp ướp bên trong: 1 thìa muối + 1/2 thìa đường + 1/4 thìa ngũ vị hương + tỏi gừng băm. Bên ngoài da chỉ cần muối và giấm."},"type":"paragraph"},{"data":{"text":"Kỹ thuật quay — lửa là tất cả","level":2},"type":"header"},{"data":{"text":"Quay heo sữa cần lửa than hồng đều, không được có ngọn lửa bùng. Giai đoạn đầu quay xa lửa 40–50 cm để thịt chín từ từ, sau đó đưa gần lửa hơn để da phồng giòn. Liên tục xoay đều tay, mỗi 5 phút một lần, tổng thời gian khoảng 60–75 phút."},"type":"paragraph"},{"data":{"text":"Cách phân biệt heo sữa quay ngon","level":2},"type":"header"},{"data":{"items":["Da màu đỏ vàng đẹp, giòn đều không bị cháy đốm","Dùng đũa gõ nhẹ lên da nghe tiếng cộp — đó là da giòn chuẩn","Thịt bên trong màu trắng hồng, không bị khô hay có nước đỏ chảy ra","Mùi thơm ngũ vị hương thoang thoảng, không bị nồng"],"style":"unordered"},"type":"list"}]}',1,0,'2026-07-15 05:44:42','2026-07-15 05:44:42','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Heo Quay Sữa Da Mỏng","url":"/images/shop/heo-sua-doi-3.jpg"}',0,NULL,'Heo quay sữa da mỏng giòn tan, thịt trắng ngọt tự nhiên. Cách chọn heo sữa đúng chuẩn và kỹ thuật quay than truyền thống.',NULL,NULL,'standard',NULL,NULL,'heo-quay-sua-da-mong-gion-tan-thit-mem-ngot-dac-trung',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlo8evn0003h93yjbqg0c9n','Bí Quyết Châm Lỗ Da Heo Trước Khi Quay — Bước Quan Trọng Nhất','{"time":1784095224804,"blocks":[{"data":{"text":"Trong tất cả các bước làm heo quay, châm lỗ da là bước nhiều người bỏ qua hoặc làm sai nhất. Đây chính là lý do da heo không giòn dù đã quay đúng nhiệt độ và thời gian."},"type":"paragraph"},{"data":{"text":"Tại sao phải châm lỗ?","level":2},"type":"header"},{"data":{"text":"Khi quay ở nhiệt độ cao, mỡ dưới da tan chảy và cần thoát ra ngoài. Nếu da không có lỗ, mỡ bị giữ lại bên dưới làm da phồng không đều, có chỗ cứng chỗ mềm. Các lỗ nhỏ cho phép mỡ thoát ra, hơi nước bay đi, tạo lớp da giòn đều khắp."},"type":"paragraph"},{"data":{"text":"Dụng cụ châm lỗ","level":2},"type":"header"},{"data":{"items":["Kim châm chuyên dụng (nhiều mũi) — nhanh và đều nhất","Nĩa inox — dùng được nhưng chậm và lỗ to","Kim khâu hoặc tăm nhọn — cho lỗ nhỏ nhất, phù hợp heo sữa","Không dùng vật sắc quá to — lỗ lớn làm da bị rách khi phồng"],"style":"unordered"},"type":"list"},{"data":{"text":"Kỹ thuật châm đúng cách","level":2},"type":"header"},{"data":{"items":["Châm vuông góc với mặt da, không xiên — tránh xé da","Mật độ: khoảng 20–30 lỗ trên mỗi 100cm² da","Châm đều khắp, chú ý vùng dày như vai và mông nhiều hơn","Không châm sâu quá 2–3mm — chỉ cần xuyên qua da, không vào thịt","Sau khi châm, xoa muối trắng lên toàn bộ da để rút ẩm"],"style":"unordered"},"type":"list"},{"data":{"text":"Sai lầm thường gặp","level":2},"type":"header"},{"data":{"items":["Châm quá ít lỗ — mỡ không thoát được, da bị phồng to không giòn","Châm quá sâu vào thịt — thịt mất nước, bị khô khi quay","Không phơi da sau khi châm — da còn ẩm, quay ra không giòn","Dùng dầu thoa lên da trước khi quay — làm da mềm thay vì giòn"],"style":"unordered"},"type":"list"}]}',0,0,'2026-07-15 06:00:26','2026-07-15 06:00:26','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Kỹ Thuật Quay Heo Trong Lò","url":"/images/shop/heo-quay-lo-1.jpg"}',0,NULL,'Kỹ thuật châm lỗ da heo trước khi quay — bước quan trọng nhất để da giòn đều. Dụng cụ và mật độ châm đúng chuẩn.',NULL,NULL,'standard',NULL,NULL,'bi-quyet-cham-lo-da-heo-truoc-khi-quay-buoc-quan-trong-nhat',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlo8fqz0007h93yarvmh0s1','Gà Quay Lu — Món Ăn Hoài Cổ Của Người Hoa Chợ Lớn','{"time":1784095224804,"blocks":[{"data":{"text":"Gà quay lu là món ăn gắn liền với ký ức của nhiều thế hệ người Hoa ở Chợ Lớn, Sài Gòn. Được quay trong chiếc lu đất nung theo kỹ thuật truyền thống hàng trăm năm tuổi, gà quay lu có hương vị và độ giòn hoàn toàn khác biệt so với bất kỳ phương pháp nào khác."},"type":"paragraph"},{"data":{"text":"Lu đất — linh hồn của món ăn","level":2},"type":"header"},{"data":{"text":"Lu dùng để quay gà là lu đất nung dày, giữ nhiệt cực tốt. Trước khi quay, lu được nung bằng than hoa từ 30–45 phút. Nhiệt từ thành lu tỏa ra đều từ mọi phía, tạo lớp da giòn đồng đều mà lò nướng điện không thể làm được."},"type":"paragraph"},{"data":{"text":"Ướp gà đúng cách cho quay lu","level":2},"type":"header"},{"data":{"items":["2 thìa ngũ vị hương","3 thìa nước tương đậm","1 thìa dầu hào","1 thìa đường phèn tán nhỏ","1 thìa mật ong","Tỏi gừng sả băm nhuyễn","Ướp tối thiểu 8 tiếng — tốt nhất 24 tiếng"],"style":"unordered"},"type":"list"},{"data":{"text":"Bí quyết da giòn của lò lu","level":2},"type":"header"},{"data":{"text":"Sau khi ướp, gà được treo trong lu bằng móc sắt, không tiếp xúc trực tiếp với lửa. Nhiệt bức xạ từ thành lu làm chín gà từ từ trong khoảng 35–45 phút. Gần xong, thợ quay sẽ phết thêm mật ong lên da và đưa gà lại gần lửa than 5 phút để da bóng vàng đẹp."},"type":"paragraph"},{"data":{"text":"Ăn gà quay lu đúng điệu","level":2},"type":"header"},{"data":{"items":["Chặt theo kiểu Quảng Đông: tách đùi, cánh, ức thành miếng vuông","Nước chấm truyền thống: xì dầu ngọt pha gừng bào","Ăn kèm cơm trắng hoặc bún tươi","Rau ăn kèm: dưa leo, ngò rí, hành phi"],"style":"unordered"},"type":"list"}]}',1,0,'2026-07-15 06:00:27','2026-07-15 06:00:27','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Món Quay Heo Quay Bình Tân","url":"/images/shop/heo-sua-doi-2.jpg"}',0,NULL,'Gà quay lu — món ăn hoài cổ của người Hoa Chợ Lớn. Kỹ thuật quay lu đất nung truyền thống cho da giòn đều và hương thơm độc đáo.',NULL,NULL,'standard',NULL,NULL,'ga-quay-lu-mon-an-hoai-co-cua-nguoi-hoa-cho-lon',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlo8hgx000fh93yvpgcnw0j','Vịt Quay Ngũ Vị — Chuẩn Vị Người Hoa Không Cần Ra Quán','{"time":1784095224804,"blocks":[{"data":{"text":"Vịt quay ngũ vị là công thức phổ biến nhất trong cộng đồng người Hoa tại TP.HCM. Không cần lò quay chuyên dụng, chỉ cần lò nướng gia đình và đúng kỹ thuật là có thể làm ra con vịt quay vàng giòn thơm lừng."},"type":"paragraph"},{"data":{"text":"Nguyên liệu ướp (cho vịt 2 kg)","level":2},"type":"header"},{"data":{"items":["2 thìa ngũ vị hương","3 thìa nước tương đậm","2 thìa dầu hào","1 thìa đường phèn tán nhỏ","1 thìa rượu Shaoxing hoặc rượu trắng","5 tép tỏi + 2 lát gừng + 1 cây sả băm nhuyễn","1 thìa muối"],"style":"unordered"},"type":"list"},{"data":{"text":"Ướp đúng cách cho vịt thấm đều","level":2},"type":"header"},{"data":{"text":"Nhồi 2/3 hỗn hợp gia vị vào bên trong bụng vịt, xoa đều. Phần còn lại xoa ngoài da. Dùng tăm khâu miệng bụng vịt lại để gia vị không chảy ra khi quay. Bọc kín, ướp trong tủ lạnh tối thiểu 8 tiếng."},"type":"paragraph"},{"data":{"text":"Lớp áo ngoài da — tạo màu và giòn","level":2},"type":"header"},{"data":{"items":["Hỗn hợp phết: mạch nha 2 thìa + giấm gạo 2 thìa + nước tương 1 thìa","Chần vịt qua nước sôi 2 phút, phết hỗn hợp ngay khi da còn nóng","Phơi khô trong tủ lạnh 12–24 tiếng","Quay 200°C / 60–70 phút, phết thêm mật ong trong 10 phút cuối"],"style":"unordered"},"type":"list"}]}',0,0,'2026-07-15 06:00:29','2026-07-15 06:00:29','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Vịt Quay Ngũ Vị Hương","url":"https://images.unsplash.com/photo-1518492104633-130d0cc84637?w=1200&q=85"}',0,NULL,'Vịt quay ngũ vị chuẩn vị người Hoa không cần ra quán. Công thức ướp, lớp áo ngoài da và kỹ thuật quay cho da vàng giòn đẹp.',NULL,NULL,'standard',NULL,NULL,'vit-quay-ngu-vi-chuan-vi-nguoi-hoa-khong-can-ra-quan',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlno7px0008h9jagh5l6fjv','Mẹo Bảo Quản Heo Quay — Giữ Da Giòn Qua Đêm Không Bị Mềm','{"time":1784094280189,"blocks":[{"data":{"text":"Heo quay ngon nhất khi ăn trong vòng 2–3 tiếng sau khi quay xong. Nhưng nếu không dùng hết, bảo quản đúng cách vẫn có thể giữ được độ giòn và hương vị tốt."},"type":"paragraph"},{"data":{"text":"Sai lầm thường gặp khi bảo quản","level":2},"type":"header"},{"data":{"items":["Bọc nilon kín ngay khi còn nóng — hơi nước làm da mềm nhũn trong vài tiếng","Để trong tủ lạnh không che — da bị khô cứng, thịt mất ẩm","Hâm lại bằng lò vi sóng — da mềm hoàn toàn không thể cứu"],"style":"unordered"},"type":"list"},{"data":{"text":"Cách bảo quản đúng","level":2},"type":"header"},{"data":{"text":"Để heo quay nguội hoàn toàn ở nhiệt độ phòng trước khi cất. Tách phần da ra khỏi thịt nếu có thể, đặt phần da hướng lên trên. Bọc nhẹ bằng giấy nến (không bọc kín) rồi cho vào tủ lạnh ngăn mát."},"type":"paragraph"},{"data":{"text":"Cách làm giòn da trở lại","level":2},"type":"header"},{"data":{"items":["Lò nướng: 220°C trong 8–10 phút, da hướng lên — hiệu quả nhất","Chảo gang: không dầu, áp phần da xuống chảo nóng già 3–4 phút","Nồi chiên không dầu: 200°C trong 5–7 phút — tiện nhất tại nhà","Tuyệt đối không dùng lò vi sóng"],"style":"unordered"},"type":"list"},{"data":{"text":"Thời gian bảo quản tối đa","level":2},"type":"header"},{"data":{"text":"Ngăn mát tủ lạnh: 3–4 ngày. Ngăn đá: 1–2 tháng (rã đông ngăn mát qua đêm). Sau khi làm giòn lại bằng lò nướng, heo quay sẽ đạt khoảng 80–90% so với ban đầu."},"type":"paragraph"}]}',0,0,'2026-07-15 05:44:43','2026-07-15 05:44:43','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Heo Quay Bảo Quản Giữ Da Giòn","url":"/images/shop/heo-quay-khay-1.jpg"}',0,NULL,'Mẹo bảo quản heo quay giữ da giòn qua đêm không bị mềm. Cách hâm lại bằng lò nướng đúng cách để da giòn trở lại.',NULL,NULL,'standard',NULL,NULL,'meo-bao-quan-heo-quay-giu-da-gion-qua-dem-khong-bi-mem',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlo8eft0001h93y9jbxiloj','Heo Quay Da Giòn Đặt Tiệc Tại Nhà — Đặt Bao Nhiêu Là Đủ?','{"time":1784095224804,"blocks":[{"data":{"text":"Câu hỏi phổ biến nhất khi đặt heo quay cho tiệc: cần bao nhiêu kg cho bao nhiêu người? Tính sai sẽ không đủ ăn hoặc lãng phí. Bài viết này giúp bạn tính đúng ngay từ đầu."},"type":"paragraph"},{"data":{"text":"Tỷ lệ tính chuẩn","level":2},"type":"header"},{"data":{"items":["Bữa chính, ăn no: 300–350g heo sống / người","Bữa tiệc có nhiều món phụ: 200–250g / người","Tiệc cúng (có xôi, canh, rau): 150–200g / người","Trẻ em dưới 10 tuổi tính bằng nửa người lớn"],"style":"unordered"},"type":"list"},{"data":{"text":"Ví dụ cụ thể","level":2},"type":"header"},{"data":{"items":["20 người ăn bữa chính: đặt 6–7 kg heo quay","30 người tiệc có nhiều món: đặt 7–8 kg","50 người tiệc cưới đủ món: đặt 10–12 kg (2 con)","100 người: đặt 4–5 con heo, mỗi con 5–6 kg"],"style":"unordered"},"type":"list"},{"data":{"text":"Nên đặt trước bao lâu?","level":2},"type":"header"},{"data":{"text":"Tiệc nhỏ dưới 30 người: đặt trước 1 ngày. Tiệc 30–100 người: đặt trước 2–3 ngày. Tiệc cưới hoặc sự kiện lớn: đặt trước 1 tuần để đảm bảo có hàng đúng ngày. Liên hệ Heo Quay Bình Tân: 0987 054 231."},"type":"paragraph"},{"data":{"text":"Mẹo nhận hàng đúng chuẩn","level":2},"type":"header"},{"data":{"items":["Nhận hàng 1–2 tiếng trước khi tiệc bắt đầu","Không để heo quay trong hộp kín khi còn nóng — da sẽ mềm","Chặt ra ngay khi khách bắt đầu ăn","Phần da nên ăn trong vòng 1 tiếng đầu"],"style":"unordered"},"type":"list"}]}',1,0,'2026-07-15 06:00:25','2026-07-15 06:00:25','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Heo Quay Đóng Hộp Giao Tận Nơi","url":"/images/shop/heo-sua-hop-3.jpg"}',0,NULL,'Hướng dẫn đặt heo quay cho tiệc tại nhà: tính số lượng kg phù hợp theo số khách, lưu ý khi nhận hàng và cách bảo quản.',NULL,NULL,'standard',NULL,NULL,'heo-quay-da-gion-dat-tiec-tai-nha-dat-bao-nhieu-la-du',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlo8irc000lh93yuroeyj7o','Heo Sữa Quay Cúng Đầy Tháng — Ý Nghĩa và Cách Chuẩn Bị','{"time":1784095224804,"blocks":[{"data":{"text":"Trong văn hóa người Việt gốc Hoa và nhiều gia đình Nam Bộ, heo sữa quay là lễ vật không thể thiếu trong lễ đầy tháng. Màu đỏ vàng của heo quay tượng trưng cho may mắn, thịnh vượng và sức khỏe cho em bé."},"type":"paragraph"},{"data":{"text":"Ý nghĩa của heo sữa trong lễ đầy tháng","level":2},"type":"header"},{"data":{"text":"Heo sữa quay trong lễ đầy tháng mang nhiều ý nghĩa: màu đỏ của da heo mang lại may mắn, heo nguyên con tượng trưng cho sự trọn vẹn đầy đủ, và việc cúng con heo nguyên thể hiện lòng thành kính với tổ tiên và thần linh phù hộ cho đứa trẻ."},"type":"paragraph"},{"data":{"text":"Cách bày mâm cúng đầy tháng có heo sữa","level":2},"type":"header"},{"data":{"items":["Heo sữa quay đặt ở vị trí trung tâm mâm cúng","Đầu heo quay về phía ban thờ","Kèm theo: xôi gấc đỏ, trái cây 5 loại, nhang đèn","Không cắt heo trước khi cúng xong","Sau khi cúng mới chặt ra cho khách ăn"],"style":"unordered"},"type":"list"},{"data":{"text":"Chọn size heo sữa phù hợp","level":2},"type":"header"},{"data":{"items":["Lễ gia đình nhỏ: heo 3–4 kg, đủ cho 10–15 người","Tiệc đầy tháng 20–30 khách: heo 5–6 kg","Tiệc lớn trên 50 khách: 2 con heo sữa hoặc 1 con heo sữa + 1 heo lớn","Đặt trước tối thiểu 2 ngày để đảm bảo có hàng đúng ngày"],"style":"unordered"},"type":"list"},{"data":{"text":"Đặt heo sữa quay tại Bình Tân","level":2},"type":"header"},{"data":{"text":"Heo Quay Bình Tân chuyên cung cấp heo sữa quay cho các dịp lễ quan trọng. Gọi 0987 054 231 để đặt hàng và được tư vấn về kích cỡ phù hợp. Giao hàng đúng giờ, đảm bảo da còn giòn khi đến tay bạn."},"type":"paragraph"}]}',1,0,'2026-07-15 06:00:31','2026-07-15 06:00:31','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Heo Sữa Quay Cúng Đầy Tháng","url":"/images/shop/heo-sua-hop-1.jpg"}',0,NULL,'Heo sữa quay cúng đầy tháng — ý nghĩa văn hóa, cách bày mâm cúng và hướng dẫn chọn size phù hợp. Đặt hàng tại Heo Quay Bình Tân.',NULL,NULL,'standard',NULL,NULL,'heo-sua-quay-cung-day-thang-y-nghia-va-cach-chuan-bi',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlo8ibt000jh93y9ax9rynf','Giá Heo Sữa Quay Bao Nhiêu? Bảng Giá và Cách Tính Chi Phí','{"time":1784095224804,"blocks":[{"data":{"text":"Heo sữa quay là món cao cấp, giá cũng cao hơn heo lớn. Bài viết này giúp bạn hiểu rõ cấu trúc giá để tránh bị hét giá hoặc mua phải hàng kém chất lượng với giá rẻ."},"type":"paragraph"},{"data":{"text":"Cấu trúc giá heo sữa quay","level":2},"type":"header"},{"data":{"items":["Giá heo sống: 250.000–350.000đ/kg (heo sữa đúng chuẩn)","Chi phí quay (than, nhân công, lu hoặc lò): 100.000–150.000đ/kg","Tổng giá thành cơ bản: 350.000–500.000đ/kg heo thành phẩm","Tỷ lệ hao hụt khi quay: 30–35% (heo 5kg sau quay còn 3.2–3.5kg)"],"style":"unordered"},"type":"list"},{"data":{"text":"Giá thị trường tham khảo (2024)","level":2},"type":"header"},{"data":{"items":["Heo sữa quay 3–4 kg: 1.200.000–1.600.000đ/con","Heo sữa quay 4–5 kg: 1.600.000–2.200.000đ/con","Heo sữa quay 5–6 kg: 2.200.000–2.800.000đ/con","Heo sữa quay lu (kỹ thuật truyền thống): cộng thêm 20–30%"],"style":"unordered"},"type":"list"},{"data":{"text":"Dấu hiệu bán giá rẻ bất thường","level":2},"type":"header"},{"data":{"text":"Heo sữa quay nguyên con 5kg mà giá dưới 1.500.000đ thì nên xem xét lại. Giá quá rẻ thường đến từ: dùng heo cai sữa giả sữa, heo không rõ nguồn gốc, da được tô màu nhân tạo, hoặc heo quay từ hôm trước hâm lại. Chọn nơi uy tín, nhận hàng trong ngày để đảm bảo chất lượng."},"type":"paragraph"},{"data":{"text":"Đặt heo sữa tại Heo Quay Bình Tân","level":2},"type":"header"},{"data":{"text":"Liên hệ 0987 054 231 để được tư vấn kích cỡ và báo giá chính xác. Chúng tôi quay heo sữa theo đơn đặt hàng, không có hàng tồn, đảm bảo tươi trong ngày. Giao hàng tận nơi trong khu vực Bình Tân và các quận lân cận."},"type":"paragraph"}]}',1,0,'2026-07-15 06:00:30','2026-07-15 06:00:30','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Heo Sữa Quay Tươi Ngon Bình Tân","url":"/images/shop/heo-sua-nho-can.jpg"}',0,NULL,'Giá heo sữa quay bao nhiêu tiền? Bảng giá tham khảo, cách tính chi phí và dấu hiệu nhận biết nơi bán giá rẻ kém chất lượng.',NULL,NULL,'standard',NULL,NULL,'gia-heo-sua-quay-bao-nhieu-bang-gia-va-cach-tinh-chi-phi',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlnxlyl0004h9xjibl2v8sq','Heo Sữa Quay Lu — Kỹ Thuật Truyền Thống Cho Da Giòn Đều Khắp','{"time":1784094719384,"blocks":[{"data":{"text":"Quay lu là kỹ thuật đặt con heo vào trong chiếc lu đất nung nóng, quay bằng nhiệt bức xạ từ thành lu thay vì tiếp xúc trực tiếp với lửa. Đây là phương pháp truyền thống của người Hoa mang lại độ giòn đều và màu sắc vàng đẹp không thể tìm thấy ở phương pháp nào khác."},"type":"paragraph"},{"data":{"text":"Lu đất — công cụ đặc biệt","level":2},"type":"header"},{"data":{"text":"Lu dùng để quay heo là loại lu đất nung chuyên dụng, cao khoảng 80–100 cm, đường kính 50–60 cm. Thành lu dày giữ nhiệt đều, không bị điểm nóng cục bộ như lò quay thông thường. Trước khi dùng, lu được nung nóng bằng than hoa trong khoảng 30 phút."},"type":"paragraph"},{"data":{"text":"Quy trình quay lu heo sữa","level":2},"type":"header"},{"data":{"items":["Bước 1: Ướp heo sữa 4–6 tiếng với ngũ vị hương, muối, đường, tỏi gừng","Bước 2: Phơi ngoài không khí 1 tiếng cho da khô hoàn toàn","Bước 3: Nung lu bằng than hoa đến khi thành lu đỏ ửng","Bước 4: Treo heo vào trong lu, đậy miệng lu bằng nắp đất","Bước 5: Quay 45–60 phút, mở kiểm tra và xoay heo giữa chừng","Bước 6: Phết mật ong trong 10 phút cuối để da bóng đẹp"],"style":"unordered"},"type":"list"},{"data":{"text":"Ưu điểm so với quay than thông thường","level":2},"type":"header"},{"data":{"items":["Da giòn đều 100% bề mặt, không có điểm cháy hay còn sống","Màu vàng đỏ đẹp tự nhiên, không cần phẩm màu","Thịt giữ ẩm tốt hơn vì nhiệt bao quanh đều","Mùi thơm đặc trưng từ đất nung — không lò nào thay thế được"],"style":"unordered"},"type":"list"}]}',0,0,'2026-07-15 05:52:02','2026-07-15 05:52:02','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Heo Sữa Quay Lu Da Giòn Đều","url":"/images/shop/heo-sua-can-1.jpg"}',0,NULL,'Heo sữa quay lu — kỹ thuật truyền thống người Hoa cho da giòn đều khắp. Quy trình quay lu đất nung và ưu điểm so với lò thông thường.',NULL,NULL,'standard',NULL,NULL,'heo-sua-quay-lu-ky-thuat-truyen-thong-cho-da-gion-deu-khap',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlnxlep0002h9xjb70w0m98','Heo Quay Sữa Nguyên Con — Tiệc Cưới, Đầy Tháng, Cúng Giỗ','{"time":1784094719384,"blocks":[{"data":{"text":"Heo quay sữa nguyên con là lựa chọn không thể thiếu trong các bữa tiệc quan trọng: cưới hỏi, đầy tháng, cúng giỗ hay tân gia. Heo sữa từ 3–6 kg với da mỏng vàng giòn, thịt trắng mềm ngọt là món sang trọng mà không phải nơi nào cũng làm được đúng chuẩn."},"type":"paragraph"},{"data":{"text":"Tại sao chọn heo sữa cho tiệc?","level":2},"type":"header"},{"data":{"items":["Da mỏng giòn rụm hơn heo lớn — ăn một miếng là nhớ mãi","Thịt trắng hồng, không mỡ dày — phù hợp mọi lứa tuổi","Trình bày đẹp nguyên con trên mâm — sang trọng, có ý nghĩa","Phần ăn vừa đủ cho 8–12 người một con"],"style":"unordered"},"type":"list"},{"data":{"text":"Kích cỡ phù hợp theo số khách","level":2},"type":"header"},{"data":{"items":["3–4 kg: tiệc nhỏ 6–8 người, ăn kèm các món khác","4–5 kg: 10–12 người, lý tưởng cho đầy tháng","5–6 kg: 12–15 người, phổ biến trong tiệc cưới","Trên 6 kg: đặt hàng trước 2 ngày, phục vụ tiệc lớn"],"style":"unordered"},"type":"list"},{"data":{"text":"Dịch vụ đặt heo sữa tại Heo Quay Bình Tân","level":2},"type":"header"},{"data":{"text":"Chúng tôi nhận đặt heo sữa nguyên con giao tận nơi hoặc khách tự đến lấy. Heo được chọn lọc kỹ, quay trong ngày, giao trong vòng 2 tiếng sau khi quay xong để đảm bảo da còn giòn. Đặt trước tối thiểu 1 ngày, tiệc lớn đặt trước 2–3 ngày."},"type":"paragraph"},{"data":{"text":"Cách thưởng thức đúng điệu","level":2},"type":"header"},{"data":{"items":["Chặt ngay khi vừa nhận — da giòn nhất trong 1–2 tiếng đầu","Ăn kèm bánh mì hoặc xôi gấc đỏ trong tiệc cúng","Nước chấm: tương hoisin pha mù tạt hoặc mắm gừng","Phần da nên ăn trước, để lâu da mềm dần"],"style":"unordered"},"type":"list"}]}',1,0,'2026-07-15 05:52:01','2026-07-15 05:52:01','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Heo Sữa Quay Cúng Đầy Tháng Kèm Xôi","url":"/images/shop/heo-sua-xoi-1.jpg"}',0,NULL,'Heo quay sữa nguyên con cho tiệc cưới, đầy tháng, cúng giỗ. Kích cỡ phù hợp theo số khách và dịch vụ đặt hàng tại Bình Tân.',NULL,NULL,'standard',NULL,NULL,'heo-quay-sua-nguyen-con-tiec-cuoi-day-thang-cung-gio',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlno7at0006h9jaet10xy60','Char Siu và Siu Yuk — Hai Món Heo Quay Kiểu Hồng Kông Khác Nhau Thế Nào?','{"time":1784094280189,"blocks":[{"data":{"text":"Trong ẩm thực Quảng Đông, có hai món heo quay nổi tiếng thế giới: Char Siu và Siu Yuk. Nhiều người nhầm lẫn hai món này, nhưng thực chất chúng hoàn toàn khác nhau về nguyên liệu, kỹ thuật và hương vị."},"type":"paragraph"},{"data":{"text":"Char Siu — thịt heo xá xíu đỏ ngọt","level":2},"type":"header"},{"data":{"text":"Char Siu dùng thịt heo thăn hoặc ba chỉ, ướp với hỗn hợp đặc trưng gồm mật ong, tương hoisin, nước tương, rượu Shaoxing. Thịt được xiên que và quay trong lò đến khi có màu đỏ nâu bóng đẹp, vị ngọt đậm đà."},"type":"paragraph"},{"data":{"text":"Siu Yuk — heo quay da giòn nguyên con","level":2},"type":"header"},{"data":{"text":"Siu Yuk là heo quay nguyên con hoặc nguyên mảng, tập trung vào lớp da giòn rụm bên ngoài. Thịt ướp gia vị nhẹ hơn Char Siu, phần da được xử lý kỹ bằng cách châm lỗ và phơi khô để đạt độ giòn tối đa."},"type":"paragraph"},{"data":{"text":"So sánh nhanh","level":2},"type":"header"},{"data":{"items":["Char Siu: thịt cắt miếng, màu đỏ ngọt, ăn với cơm trắng hoặc bún","Siu Yuk: nguyên con hoặc mảng, da vàng giòn, dùng trong tiệc và lễ cúng","Char Siu phổ biến ở dim sum; Siu Yuk phổ biến trong tiệc tùng"],"style":"unordered"},"type":"list"},{"data":{"text":"Cách làm Char Siu tại nhà","level":2},"type":"header"},{"data":{"text":"Ướp 500g thịt ba chỉ với: 2 thìa tương hoisin + 1 thìa mật ong + 1 thìa nước tương + 1/2 thìa ngũ vị hương + 1 thìa rượu trắng + 1 thìa đường. Ướp 4 tiếng. Nướng 200°C trong 25 phút, lật và phết thêm mật ong, nướng thêm 10 phút cho bóng đẹp."},"type":"paragraph"}]}',1,0,'2026-07-15 05:44:43','2026-07-15 05:44:43','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Heo Quay Kiểu Hoa","url":"/images/shop/heo-quay-can-2.jpg"}',0,NULL,'Phân biệt Char Siu và Siu Yuk — hai món heo quay kiểu Hồng Kông. Công thức Char Siu tại nhà đơn giản, da bóng ngọt đậm đà.',NULL,NULL,'standard',NULL,NULL,'char-siu-va-siu-yuk-hai-mon-heo-quay-kieu-hong-kong-khac-nhau-the-nao',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlnoanx000mh9jagnod3gjq','Mẹo Khử Mùi Tanh Của Vịt — Làm Sạch Đúng Cách Trước Khi Quay','{"time":1784094280189,"blocks":[{"data":{"text":"Mùi tanh của vịt là rào cản lớn nhất khiến nhiều người ngại nấu vịt tại nhà. Thực ra, khử mùi vịt không khó nếu biết đúng cách — và đây là bước quan trọng nhất quyết định chất lượng món vịt quay."},"type":"paragraph"},{"data":{"text":"Tại sao vịt có mùi tanh?","level":2},"type":"header"},{"data":{"text":"Vịt có tuyến dầu ở đuôi (tuyến nhờn) tiết ra chất dầu để vịt bơi không bị ướt lông. Đây là nguồn gốc chính của mùi tanh. Ngoài ra, phần mỡ dưới da vịt cũng chứa nhiều axit béo tạo mùi khi gặp nhiệt."},"type":"paragraph"},{"data":{"text":"Các bước khử mùi hiệu quả","level":2},"type":"header"},{"data":{"items":["Bước 1: Cắt bỏ tuyến nhờn ở đuôi vịt — quan trọng nhất, không được bỏ qua","Bước 2: Chà xát toàn thân vịt với muối hột và giấm trong 5 phút, rửa sạch","Bước 3: Chần vịt qua nước sôi có gừng đập dập và sả cây trong 3 phút","Bước 4: Rửa lại bằng nước lạnh, để ráo","Bước 5: Xoa gừng tươi bào vào bên trong bụng vịt trước khi ướp"],"style":"unordered"},"type":"list"},{"data":{"text":"Mẹo chọn vịt ít tanh từ đầu","level":2},"type":"header"},{"data":{"text":"Vịt cỏ (vịt đồng) và vịt xiêm ít tanh hơn vịt bầu nuôi công nghiệp. Vịt trống (vịt đực) ít tanh hơn vịt mái. Vịt khoảng 2 kg là chuẩn nhất — quá già sẽ tanh và dai hơn."},"type":"paragraph"}]}',0,0,'2026-07-15 05:44:47','2026-07-15 05:44:47','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Sơ Chế Vịt Sạch Trước Khi Quay","url":"https://images.unsplash.com/photo-1518492104633-130d0cc84637?w=1200&q=85"}',0,NULL,'Cách khử mùi tanh của vịt trước khi quay — các bước sơ chế đúng và mẹo chọn vịt ít tanh từ đầu để món quay thơm ngon.',NULL,NULL,'standard',NULL,NULL,'meo-khu-mui-tanh-cua-vit-lam-sach-dung-cach-truoc-khi-quay',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlo8fbd0005h93yh5hw9uxj','Heo Quay Cả Con — Từ Chọn Heo Đến Khi Lên Mâm','{"time":1784095224804,"blocks":[{"data":{"text":"Quay heo cả con là kỹ thuật đòi hỏi kinh nghiệm, nhưng nếu nắm đúng từng bước thì hoàn toàn có thể thực hiện được. Bài viết này tổng hợp toàn bộ quy trình từ A đến Z."},"type":"paragraph"},{"data":{"text":"Chọn heo","level":2},"type":"header"},{"data":{"items":["Heo 15–20 kg là kích cỡ lý tưởng cho quay cả con","Da trắng hồng, không bầm, lông đã cạo sạch","Heo đã mổ sạch, bỏ nội tạng, rửa kỹ bên trong","Mua từ lò mổ uy tín, có kiểm dịch"],"style":"unordered"},"type":"list"},{"data":{"text":"Ướp gia vị","level":2},"type":"header"},{"data":{"text":"Hỗn hợp ướp bên trong (cho heo 15–20 kg): 100g muối + 50g đường + 30g ngũ vị hương + 20g bột tỏi + 20g bột gừng + 100ml rượu trắng. Trộn đều, xoa kỹ vào toàn bộ bên trong bụng heo. Ướp tối thiểu 6 tiếng, tốt nhất 12 tiếng."},"type":"paragraph"},{"data":{"text":"Xử lý da trước khi quay","level":2},"type":"header"},{"data":{"items":["Châm lỗ toàn bộ da bằng kim chuyên dụng","Xoa hỗn hợp giấm trắng + muối lên da, để 15 phút","Rửa sạch, lau khô bằng khăn sạch","Phơi ngoài không khí tối thiểu 2 tiếng, tốt nhất qua đêm trong tủ lạnh không che"],"style":"unordered"},"type":"list"},{"data":{"text":"Quy trình quay","level":2},"type":"header"},{"data":{"items":["Nhiệt độ ban đầu 200–220°C trong 30 phút để da phồng","Hạ xuống 170–180°C quay tiếp 60–90 phút tùy trọng lượng","Phết hỗn hợp mật ong + nước tương trong 15 phút cuối","Tổng thời gian: khoảng 2–2.5 tiếng cho heo 15–20 kg","Kiểm tra bằng cách xiên vào phần dày nhất — không có nước hồng chảy ra là chín"],"style":"unordered"},"type":"list"}]}',0,0,'2026-07-15 06:00:26','2026-07-15 06:00:26','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Heo Quay Cả Con Tươi Ngon","url":"/images/shop/heo-quay-can-1.jpg"}',0,NULL,'Hướng dẫn quay heo cả con từ A đến Z: chọn heo, ướp gia vị, xử lý da và kỹ thuật quay đúng nhiệt độ cho heo 15–20 kg.',NULL,NULL,'standard',NULL,NULL,'heo-quay-ca-con-tu-chon-heo-den-khi-len-mam',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlo8g6f0009h93yse4r0ilc','Gà Quay Mật Ong Tỏi Ớt — Da Giòn Ngọt Cay Khó Cưỡng','{"time":1784095224804,"blocks":[{"data":{"text":"Biến tấu từ gà quay mật ong cổ điển, phiên bản tỏi ớt thêm vào một chiều hương vị mới: ngọt thanh của mật ong, cay nồng của ớt, thơm nức của tỏi phi vàng. Đây là công thức được nhiều gia đình trẻ ưa chuộng nhất hiện nay."},"type":"paragraph"},{"data":{"text":"Nguyên liệu ướp","level":2},"type":"header"},{"data":{"items":["3 thìa mật ong","2 thìa nước tương","1 thìa dầu hào","1 thìa tương ớt Sriracha (hoặc ớt bột Hàn Quốc)","6 tép tỏi băm nhuyễn","2 thìa dầu mè","1 thìa đường nâu","Muối tiêu vừa đủ"],"style":"unordered"},"type":"list"},{"data":{"text":"Kỹ thuật phết mật ong nhiều lần","level":2},"type":"header"},{"data":{"text":"Bí quyết tạo lớp da bóng đẹp của công thức này là phết mật ong ít nhất 3 lần trong quá trình quay. Lần 1 khi bắt đầu quay. Lần 2 sau 20 phút. Lần 3 trong 5 phút cuối cùng với lửa cao. Mỗi lần phết, lật gà để mặt kia tiếp lửa. Kết quả là lớp áo mật ong caramel hóa đẹp, giòn và thơm."},"type":"paragraph"},{"data":{"text":"Lưu ý khi dùng tỏi ớt","level":2},"type":"header"},{"data":{"items":["Ướp tỏi sống vào thịt — tỏi thấm sâu tạo hương thơm","Khi quay, tỏi trên da dễ cháy — dùng giấy bạc che phần tỏi nếu thấy quá đen","Ớt bột Hàn Quốc cho màu đỏ đẹp và ít cay hơn ớt Việt","Sau khi ra lò, rắc thêm tỏi phi vàng để tăng mùi thơm"],"style":"unordered"},"type":"list"}]}',0,0,'2026-07-15 06:00:27','2026-07-15 06:00:27','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Gà Quay Mật Ong Tỏi Ớt","url":"https://images.unsplash.com/photo-1527477396000-e27163b481c2?w=1200&q=85"}',0,NULL,'Gà quay mật ong tỏi ớt — da giòn ngọt cay khó cưỡng. Công thức phết mật ong nhiều lần và bí quyết không để tỏi cháy.',NULL,NULL,'standard',NULL,NULL,'ga-quay-mat-ong-toi-ot-da-gion-ngot-cay-kho-cuong',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlo8h1c000dh93yesnml61b','Vịt Quay Bắc Kinh Tại Nhà — Có Thể Làm Không?','{"time":1784095224804,"blocks":[{"data":{"text":"Vịt quay Bắc Kinh (Peking Duck) là một trong những món nổi tiếng nhất thế giới, thường chỉ thấy ở nhà hàng cao cấp. Nhưng với lò nướng gia đình hiện đại, bạn hoàn toàn có thể làm được phiên bản gần chuẩn — không cần lò đặc biệt."},"type":"paragraph"},{"data":{"text":"Điều làm Vịt Quay Bắc Kinh khác biệt","level":2},"type":"header"},{"data":{"text":"Bí quyết của Peking Duck không phải ở gia vị mà ở kỹ thuật tạo da giòn mỏng như giấy. Da vịt được bơm hơi để tách khỏi thịt, sau đó phết hỗn hợp mạch nha và phơi khô trong phòng lạnh ít nhất 24 tiếng. Quá trình này loại bỏ hoàn toàn độ ẩm khỏi da, tạo ra lớp da giòn cực mỏng khi quay."},"type":"paragraph"},{"data":{"text":"Phiên bản rút gọn tại nhà","level":2},"type":"header"},{"data":{"items":["Chần vịt qua nước sôi 2 phút để da căng","Phết hỗn hợp mạch nha + giấm gạo (tỷ lệ 2:1) lên toàn da khi còn nóng","Treo trong tủ lạnh không che 24–48 tiếng (quan trọng nhất)","Quay 220°C trong 15 phút, hạ 180°C quay tiếp 40 phút","Lật vịt giữa chừng để chín đều"],"style":"unordered"},"type":"list"},{"data":{"text":"Cách ăn đúng điệu Bắc Kinh","level":2},"type":"header"},{"data":{"items":["Cắt da thành miếng nhỏ 3x5cm, ăn da riêng trước","Cuốn bánh mì chiên mỏng (bánh bao chiên) với da vịt + dưa leo + hành lá","Chấm tương hoisin","Thịt vịt nấu cháo hoặc xào với giá đỗ — dùng tiếp sau khi ăn da"],"style":"unordered"},"type":"list"}]}',0,0,'2026-07-15 06:00:28','2026-07-15 06:00:28','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Vịt Quay Bắc Kinh Da Giòn","url":"https://images.unsplash.com/photo-1518492104633-130d0cc84637?w=1200&q=85"}',0,NULL,'Vịt quay Bắc Kinh tại nhà — có thể làm không? Hướng dẫn phiên bản rút gọn với lò gia đình và cách ăn đúng điệu Bắc Kinh.',NULL,NULL,'standard',NULL,NULL,'vit-quay-bac-kinh-tai-nha-co-the-lam-khong',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlo8hwe000hh93ynwzc0duf','Vịt Quay Kèm Bún — Cách Làm Tô Bún Vịt Thơm Ngon Tại Nhà','{"time":1784095224804,"blocks":[{"data":{"text":"Vịt quay ăn với bún là một trong những cách thưởng thức phổ biến nhất — nước dùng từ xương vịt quay ngọt thanh, bún trắng mềm, thịt vịt giòn da là sự kết hợp hoàn hảo."},"type":"paragraph"},{"data":{"text":"Nước dùng từ xương vịt quay","level":2},"type":"header"},{"data":{"text":"Sau khi lấy hết phần thịt và da ngon nhất, phần xương vịt quay là nguyên liệu tuyệt vời để nấu nước dùng. Cho xương vào nồi, thêm gừng đập dập, sả cây, hành tím nướng, đổ 2 lít nước, nấu sôi rồi hạ lửa hầm 1 tiếng. Nêm muối, đường, nước mắm vừa ăn."},"type":"paragraph"},{"data":{"text":"Topping và rau ăn kèm","level":2},"type":"header"},{"data":{"items":["Thịt vịt quay thái miếng, da còn giòn","Cải xanh trụng qua nước sôi","Hành lá, ngò rí thái nhỏ","Gừng bào sợi","Chanh, ớt tươi","Tương hoisin và tương ớt để chấm"],"style":"unordered"},"type":"list"},{"data":{"text":"Cách trình bày tô bún đẹp","level":2},"type":"header"},{"data":{"items":["Trụng bún qua nước sôi, cho vào tô","Xếp thịt vịt lên trên — da phải hướng lên để giữ giòn","Chan nước dùng nóng vào tô (không đổ lên da)","Rắc hành ngò, gừng bào lên trên","Dọn ngay — để lâu da sẽ mềm"],"style":"unordered"},"type":"list"}]}',1,0,'2026-07-15 06:00:30','2026-07-15 06:00:30','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Món Quay Heo Quay Bình Tân","url":"/images/shop/heo-sua-hop-2.jpg"}',0,NULL,'Cách làm tô bún vịt quay thơm ngon tại nhà — nước dùng từ xương vịt quay ngọt thanh, thịt giòn da, rau ăn kèm đúng vị.',NULL,NULL,'standard',NULL,NULL,'vit-quay-kem-bun-cach-lam-to-bun-vit-thom-ngon-tai-nha',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrltx2e40001h9yrxros6zy1','Gà Nướng Bình Tân — Vàng Giòn, Thơm Lừng, Giao Tận Nơi','{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Gà Nướng Bình Tân — Vàng Giòn, Thơm Lừng, Giao Tận Nơi","type":"text"}]}]}',0,0,'2026-07-15 08:39:34','2026-07-15 08:39:34','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Gà Nướng Bình Tân","url":"/images/shop/heo-sua-khay-2.jpg"}',0,NULL,'Gà nướng than hoa tươi ngon tại Bình Tân. Thịt ngọt, da vàng giòn, giao hàng trong ngày. Đặt gà nướng cho tiệc, cúng giỗ tại Heo Quay Bình Tân.',NULL,NULL,'standard',NULL,NULL,'ga-nuong-binh-tan-vang-gion-thom-lung-giao-tan-noi',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrltx2s70003h9yrxcw2w19h','Giá Gà Nướng Tại Heo Quay Bình Tân — Bảng Giá Mới Nhất','{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Giá Gà Nướng Tại Heo Quay Bình Tân — Bảng Giá Mới Nhất","type":"text"}]}]}',0,0,'2026-07-15 08:39:34','2026-07-15 08:39:34','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Giá Gà Nướng Bình Tân","url":"/images/shop/heo-sua-doi-2.jpg"}',0,NULL,'Bảng giá gà nướng tại Heo Quay Bình Tân. Gà nướng nguyên con, nửa con giá tốt. Đặt hàng giao tận nhà khu vực Bình Tân, TP.HCM.',NULL,NULL,'standard',NULL,NULL,'gia-ga-nuong-tai-heo-quay-binh-tan-bang-gia-moi-nhat',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrltx3620005h9yr7el5ykfw','Vịt Nướng Bình Tân — Da Giòn, Thịt Đậm Vị, Đặt Là Có','{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Vịt Nướng Bình Tân — Da Giòn, Thịt Đậm Vị, Đặt Là Có","type":"text"}]}]}',0,0,'2026-07-15 08:39:35','2026-07-15 08:39:35','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Vịt Nướng Bình Tân","url":"/images/shop/heo-sua-can-1.jpg"}',0,NULL,'Vịt nướng tươi ngon tại Bình Tân. Da giòn, thịt đậm vị, không tanh. Đặt vịt nướng nguyên con cho tiệc, cúng giỗ — giao hàng trong ngày.',NULL,NULL,'standard',NULL,NULL,'vit-nuong-binh-tan-da-gion-thit-dam-vi-dat-la-co',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlno9eq000gh9jasvfz1qmn','Bí Quyết Chọn Gà Ngon Cho Món Quay — Gà Ta Hay Gà Công Nghiệp?','{"time":1784094280189,"blocks":[{"data":{"text":"Câu hỏi thường gặp nhất khi làm gà quay: dùng gà ta hay gà công nghiệp? Câu trả lời không đơn giản — mỗi loại có ưu nhược điểm riêng và phù hợp với từng công thức khác nhau."},"type":"paragraph"},{"data":{"text":"Gà ta (gà đồi, gà thả vườn)","level":2},"type":"header"},{"data":{"items":["Thịt chắc, dai vừa, vị ngọt tự nhiên đậm hơn","Da mỏng, giòn đẹp khi quay — lý tưởng cho gà quay da giòn","Mỡ ít, thịt không bị ngấy dù ăn nhiều","Nhược điểm: giá cao hơn, khó mua gà đồng đều kích cỡ"],"style":"unordered"},"type":"list"},{"data":{"text":"Gà công nghiệp (gà thịt, gà tam hoàng)","level":2},"type":"header"},{"data":{"items":["Thịt mềm, nhiều nước, ít dai hơn","Da dày hơn — cần thêm kỹ thuật để đạt độ giòn","Kích cỡ đồng đều, dễ mua số lượng lớn","Phù hợp cho công thức ướp đậm như gà quay mật ong"],"style":"unordered"},"type":"list"},{"data":{"text":"Cách nhận biết gà ta tươi ngoài chợ","level":2},"type":"header"},{"data":{"text":"Gà ta tươi có da màu vàng nhạt tự nhiên, thịt ức nhỏ so với thân gà, chân nhỏ và có vảy rõ. Khi ấn vào thịt đàn hồi ngay. Gà thả vườn thật sự thường có da đôi chỗ hơi xanh — đó là dấu hiệu tốt, không phải xấu."},"type":"paragraph"}]}',0,0,'2026-07-15 05:44:45','2026-07-15 05:44:45','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Chọn Gà Tươi Ngon Cho Món Quay","url":"https://images.unsplash.com/photo-1527477396000-e27163b481c2?w=1200&q=85"}',0,NULL,'Bí quyết chọn gà ngon cho món quay: phân biệt gà ta và gà công nghiệp, nhận biết gà tươi tại chợ và chọn đúng loại theo từng công thức.',NULL,NULL,'standard',NULL,NULL,'bi-quyet-chon-ga-ngon-cho-mon-quay-ga-ta-hay-ga-cong-nghiep',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO `posts` VALUES ('cmrlo8glv000bh93ygiq99m4o','Cách Chặt Gà Quay Đúng Kiểu — Đẹp Mắt và Không Mất Da','{"time":1784095224804,"blocks":[{"data":{"text":"Chặt gà quay tưởng đơn giản nhưng làm sai sẽ làm da bị bong, thịt vỡ không đẹp. Chặt đúng kỹ thuật giúp dĩa gà trình bày được, da giữ nguyên vẹn và thịt không bị khô."},"type":"paragraph"},{"data":{"text":"Dụng cụ cần thiết","level":2},"type":"header"},{"data":{"items":["Dao chặt nặng, sắc — lưỡi dao phải đủ nặng để chặt qua xương một nhát","Thớt gỗ dày tối thiểu 5cm — không dùng thớt nhựa mỏng, dao dễ trượt","Khăn sạch lót dưới thớt để không trượt"],"style":"unordered"},"type":"list"},{"data":{"text":"Thứ tự chặt gà đúng cách","level":2},"type":"header"},{"data":{"items":["Bước 1: Để gà nghỉ 5–10 phút sau khi ra lò trước khi chặt","Bước 2: Tách 2 đùi — dùng dao rạch da nơi đùi nối thân, bẻ nhẹ ra ngoài rồi cắt","Bước 3: Tách 2 cánh — rạch tại khớp vai, bẻ ngược và cắt","Bước 4: Tách đầu cổ riêng","Bước 5: Chặt ức thành miếng ngang dày 2–3cm","Bước 6: Chặt lưng thành 3–4 miếng","Bước 7: Chặt đùi và cánh thành miếng vừa ăn"],"style":"unordered"},"type":"list"},{"data":{"text":"Mẹo giữ da không bị bong","level":2},"type":"header"},{"data":{"items":["Chặt dứt khoát một nhát, không cưa tới lui — da sẽ bong","Chặt vuông góc với thớt, không chặt xiên","Không dùng dao sắc quá mỏng — lưỡi dao mỏng dễ bị kẹt xương làm xé da","Bày ra dĩa ngay sau khi chặt xong, đừng để lâu"],"style":"unordered"},"type":"list"}]}',0,0,'2026-07-15 06:00:28','2026-07-15 06:00:28','cmrlnetjs0000h9ri0mx0cwfp','{"alt":"Gà Quay Chặt Miếng Đẹp","url":"https://images.unsplash.com/photo-1527477396000-e27163b481c2?w=1200&q=85"}',0,NULL,'Hướng dẫn chặt gà quay đúng kiểu — đẹp mắt, không bong da, thịt không vỡ. Thứ tự chặt và mẹo giữ da nguyên vẹn.',NULL,NULL,'standard',NULL,NULL,'cach-chat-ga-quay-dung-kieu-dep-mat-va-khong-mat-da',NULL,0,1,NULL,NULL,NULL,NULL,NULL,NULL,0);
